using System;using System.IO;using System.Text;using System.Security.Cryptography;using System.Web.Script.Serialization;
class FeatureTests {
 static int passed;static void Check(bool ok,string name){if(!ok)throw new Exception(name);passed++;Console.WriteLine("PASS "+name);}
 static void Reject(Action action,string name){try{action();}catch{Check(true,name);return;}throw new Exception("Accepted unsafe input: "+name);}
 static JavaScriptSerializer json=new JavaScriptSerializer();
 static string Envelope(string payload,RSACryptoServiceProvider rsa){var b=Encoding.UTF8.GetBytes(payload);return json.Serialize(new{payload=Convert.ToBase64String(b),signature=Convert.ToBase64String(rsa.SignData(b,"SHA256"))});}
 static void Main(){try{Run();}catch(Exception e){Console.WriteLine("FAIL "+e.Message);Environment.ExitCode=1;}} static void Run(){string root=Path.Combine(Path.GetTempPath(),"WidgetTests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
  Directory.CreateDirectory(Path.Combine(root,"account"));File.WriteAllText(Path.Combine(root,"account","auth.json"),"SYNTHETIC_ONLY");File.WriteAllText(Path.Combine(root,"settings.json"),"{\"mini\":true,\"full\":false,\"topmost\":false}");
  var store=new AccountStore(root,false);Check(store.Entries.Count==1&&store.Entries[0].Id=="legacy","legacy managed account migrates");
  var old=store.Entries[0];store.SetIdentity(old,"fixture@example.invalid","workspace-a");var pending=store.Prepare("업무");store.Cancel(pending);Check(store.Entries.Count==1&&File.ReadAllText(Path.Combine(root,"account","auth.json"))=="SYNTHETIC_ONLY","cancel preserves old credentials");
  pending=store.Prepare("조회 중 취소");using(var cancelled=new System.Threading.CancellationTokenSource()){cancelled.Cancel();Reject(()=>store.Commit(pending,"cancelled@example.invalid","workspace-c",cancelled.Token),"cancel after account read prevents commit");}Check(store.Entries.Count==1&&pending.Kind=="pending","cancelled quota fetch cannot add account");store.Cancel(pending);
  SafeJson.Write(Path.Combine(root,"status.json"),new{snapshot=new{ShortUsed=43.5,WeekUsed=(double?)null,DailyTokens=new System.Collections.Generic.Dictionary<string,long?>{{"2026-11-13",1200},{"2026-11-12",0},{"2026-11-11",null}}}});LegacyCache.Migrate(root,store.Entries);string migrated=File.ReadAllText(Path.Combine(root,"cache","legacy.json"));Check(migrated.Contains("43.5")&&migrated.Contains("1200")&&migrated.Contains("2026-11-12\":0")&&migrated.Contains("2026-11-11\":null"),"v1 snapshot migration retains stale quota daily zero and unknown");SafeJson.Write(Path.Combine(root,"status.json"),new{running=true});LegacyCache.Migrate(root,store.Entries);Check(File.ReadAllText(Path.Combine(root,"cache","legacy.json"))==migrated,"later status saves cannot erase migrated cache");
  string broken=Path.Combine(root,"broken-v1");Directory.CreateDirectory(Path.Combine(broken,"account"));File.WriteAllText(Path.Combine(broken,"account","auth.json"),"SYNTHETIC_ONLY");File.WriteAllText(Path.Combine(broken,"status.json"),"{truncated");var brokenStore=new AccountStore(broken,false);LegacyCache.Migrate(broken,brokenStore.Entries);Check(brokenStore.Entries.Count==1&&File.ReadAllText(Path.Combine(broken,"account","auth.json"))=="SYNTHETIC_ONLY"&&File.ReadAllText(Path.Combine(broken,"legacy-status-unreadable.json"))=="{truncated","malformed legacy status does not block startup or lose credentials");
  string nested=Path.Combine(root,"account","plugins","cache","not-owned-by-widget");Directory.CreateDirectory(nested);File.WriteAllText(Path.Combine(nested,"cache.fixture"),"UNNEEDED_RUNTIME_CACHE");string backup=Path.Combine(root,"private-backup");WidgetBackup.Create(root,backup);Check(File.ReadAllText(Path.Combine(backup,"account","auth.json"))=="SYNTHETIC_ONLY"&&File.Exists(Path.Combine(backup,"settings.json"))&&File.Exists(Path.Combine(backup,"status.json"))&&File.Exists(Path.Combine(backup,"cache","legacy.json"))&&!Directory.Exists(Path.Combine(backup,"account","plugins")),"backup retains credentials settings history without descending into plugin caches");Check(File.Exists(Path.Combine(nested,"cache.fixture")),"backup never moves or deletes source caches");
  pending=store.Prepare("추가");Reject(()=>store.Commit(pending,"fixture@example.invalid","workspace-a"),"duplicate account rejected");store.Cancel(pending);Check(store.Entries.Count==1,"duplicate does not replace account");
  pending=store.Prepare("조회 실패 계정");Reject(()=>store.Commit(pending,"fixture@example.invalid",null),"duplicate with unavailable quota identity rejected");store.Cancel(pending);
  Reject(()=>store.AddPc("중복 PC","fixture@example.invalid","workspace-a"),"PC connection cannot duplicate existing independent account");Check(store.Entries.Count==1,"rejected PC duplicate preserves previous accounts");var pc=store.AddPc("다른 PC 계정","pc@example.invalid","workspace-p");Check(store.Entries.Count==2&&pc.Kind=="pc","distinct PC account can be added independently");store.Remove(pc);
  pending=store.Prepare("공부");var added=store.Commit(pending,"other@example.invalid","workspace-b");Check(store.Entries.Count==2&&store.Home(added)!=store.Home(old),"account homes isolated");
  Check(new AccountStore(root,false).Entries.Count==2,"account list survives reload");Check(File.ReadAllText(Path.Combine(root,"settings.json")).Contains("\"mini\":true"),"migration preserves visibility settings");
  Reject(()=>store.Home(new AccountEntry{Id="../../outside",Kind="managed"}),"account path traversal rejected");
  store.Remove(added);Check(store.Entries.Count==1&&File.Exists(Path.Combine(root,"account","auth.json")),"remove affects only chosen account");
  Check(BoardColors.Band(0)=="red"&&BoardColors.Band(10)=="red"&&BoardColors.Band(10.1)=="orange"&&BoardColors.Band(50)=="orange"&&BoardColors.Band(50.1)=="blue"&&BoardColors.Band(80)=="blue"&&BoardColors.Band(80.1)=="green","quota color boundaries");
  using(var rsa=new RSACryptoServiceProvider(2048)){string pub=rsa.ToXmlString(false);string payload=json.Serialize(new{version="2.0.1",package_url="https://github.com/peter0153/token-usage-widget/releases/download/v2.0.1/TokenWidget-2.0.1-win64.zip",sha256=new string('a',64),size=100L,notes="Fixture update"});
   string signed=Envelope(payload,rsa);var v=UpdatePolicy.Read(signed,pub,new Version(2,0,0),"peter0153/token-usage-widget");Check(v.Version=="2.0.1","valid signed update accepted");
   Check(UpdatePolicy.Read(signed,pub,new Version(2,0,1),"peter0153/token-usage-widget")==null,"same version is not an update");Check(UpdatePolicy.Read(signed,pub,new Version(2,0,2),"peter0153/token-usage-widget")==null,"downgrade ignored");
   Reject(()=>UpdatePolicy.Read(signed.Replace("signature","changed"),pub,new Version(2,0,0),"peter0153/token-usage-widget"),"missing signature rejected");
   Reject(()=>UpdatePolicy.Read(Envelope(payload.Replace("peter0153/token-usage-widget","other/repo"),rsa),pub,new Version(2,0,0),"peter0153/token-usage-widget"),"wrong repository rejected");
   Reject(()=>UpdatePolicy.Read(Envelope(payload.Replace("https:","http:"),rsa),pub,new Version(2,0,0),"peter0153/token-usage-widget"),"insecure update URL rejected");
   Reject(()=>UpdatePolicy.Read(Envelope(payload.Replace(new string('a',64),"broken"),rsa),pub,new Version(2,0,0),"peter0153/token-usage-widget"),"malformed package digest rejected");
   using(var other=new RSACryptoServiceProvider(2048)){Reject(()=>UpdatePolicy.Read(signed,other.ToXmlString(false),new Version(2,0,0),"peter0153/token-usage-widget"),"wrong signing key rejected");}
  }
  var oldDays=new System.Collections.Generic.Dictionary<string,long?>{{"2026-11-15",1000},{"2026-11-14",0}};Check(DailyHistory.CopyForAccount(oldDays,"account-a",null,"account-b","identity-b").Count==0,"switching PC account cannot inherit previous account daily tokens");Check(DailyHistory.CopyForAccount(oldDays,"account-a",null,"account-a","identity-a").Count==2,"same account retains history when server daily usage is unavailable");Check(DailyHistory.CopyForAccount(oldDays,null,null,null,"identity-a").Count==0,"unknown cached account identity cannot be attributed to a new login");
  var rows=DailyHistory.Rows(oldDays,new System.Collections.Generic.Dictionary<string,long?>{{"2026-11-13",300}},50,new DateTime(2026,11,16),5);Check(rows.Count==5&&rows[0].Tokens==null&&rows[1].Tokens==300&&rows[1].Local&&rows[2].Tokens==0&&!rows[2].Local&&rows[4].Tokens==50&&rows[4].Local,"history keeps missing zero and PC versus server sources distinct");Check(DailyHistory.Rows(null,null,null,DateTime.Today,10).Count==10,"ten day range includes exactly ten calendar dates");
  Check(AccountExtras.ParseCount("{\"availableCount\":0}")==0&&AccountExtras.ParseCount("{\"rate_limit_reset_credits\":{\"available_count\":3}}")==3,"reset credit zero and available counts parsed without inventing data");Reject(()=>AccountExtras.ParseCount("{}"),"missing reset count is unknown rather than zero");Reject(()=>AccountExtras.ParseCount("{\"availableCount\":1.5}"),"fractional reset credit count rejected");
  Check(MiniBarRenderer.ClampWidth(90)==148&&MiniBarRenderer.ClampWidth(600)==360&&MiniBarRenderer.DragWidth(224,40,1)==184&&MiniBarRenderer.DragWidth(224,-60,1.5f)==264,"mini width drag respects DPI and safe limits");
  Check(DailyUsageView.CheckMissingAndZero()&&ResetCountdown.CheckBoundaries(),"missing zero and reset boundaries retained");Console.WriteLine("PASS feature assertions: "+passed);
 }
}
